#ifndef TSASM_H
#define TSASM_H
#include <stdint.h>

// field: the node's grammar field id, 0 for none, as ts_tree_cursor_current_field_id gives it (the
// field from its parent's production, else from its nearest hidden ancestors'; none on an extra).
typedef struct { uint16_t symbol; uint8_t named; uint8_t field; uint32_t start_byte; uint32_t end_byte; int32_t parent; } TsasmNode; // 16 bytes

// A grammar's tables and lexer, generated by gen/gen.py from tree-sitter's parser.c. Read-only
// and shared by all threads. The library is built with one tsasm_language_<name>() per grammar.
typedef struct TsasmLanguage TsasmLanguage;
const TsasmLanguage *tsasm_language_go(void);   // tree-sitter-go v0.25.0
const TsasmLanguage *tsasm_language_c(void);    // tree-sitter-c v0.24.2
const TsasmLanguage *tsasm_language_java(void); // tree-sitter-java v0.23.5
const TsasmLanguage *tsasm_language_json(void); // tree-sitter-json v0.24.8

// A parser owns all mutable parse state: its buffers, its output array and its limits. The
// library has no other writable state, so threads may parse at the same time as long as each
// call uses its own parser. One parser serves one call at a time; it may move between threads.
typedef struct TsasmParser TsasmParser;

// Returns NULL if out of memory. The memory limit starts at TSASM_DEFAULT_MEMORY_LIMIT.
TsasmParser *tsasm_parser_new(void);
// Frees the parser, its buffers and its output array. NULL is ignored.
void tsasm_parser_free(TsasmParser *p);
// Caps the bytes the parser may hold: parse buffers plus the output array. A parse that would
// exceed it returns TSASM_ERR_LIMIT. Buffers kept from earlier parses count, so lowering the
// limit below current use frees them, including the node array of the last parse.
void tsasm_parser_set_memory_limit(TsasmParser *p, uint64_t bytes);
#define TSASM_DEFAULT_MEMORY_LIMIT (1ull << 30)
// Caps the bytes of buffers a parser keeps between parses (TSASM_DEFAULT_RETAIN to start). A parse
// that needed more frees its working buffers before it returns, keeping only the node array it
// returns, and the next parse frees that too. Kept buffers make the next big parse faster; freed
// ones come back zeroed by the kernel. Many threads parsing big files: 32 MiB costs no speed, 8 MiB
// uses about a fifth less peak memory but parses 20-30% slower. Lowering it below current use frees
// the buffers now, including the node array of the last parse.
void tsasm_parser_set_retain(TsasmParser *p, uint64_t bytes);
#define TSASM_DEFAULT_RETAIN (32ull << 20)

// Parses src with lang. On success returns the node count and sets *nodes to the tree's VISIBLE nodes
// (named and anonymous, as C tree-sitter's ts_node_child walk shows them) in pre-order; parent is
// the index of the parent in that array, -1 for the root. The array belongs to the parser and stays
// valid until the next tsasm_parse or tsasm_parser_free on it. On failure returns a negative
// TSASM_ERR_* code and sets *nodes to NULL. nodes may be NULL to only check that the source parses.
int64_t tsasm_parse(TsasmParser *p, const TsasmLanguage *lang, const uint8_t *src, uint64_t len,
                    const TsasmNode **nodes);

#define TSASM_ERR_SYNTAX (-1) // no parse: C tree-sitter would return a tree with errors (there is no error recovery)
#define TSASM_ERR_LIMIT (-3)  // a budget ran out: the memory limit, the work budget (64 units per input byte),
                              // 2^27 tree nodes, or an input of 4 GiB or more
#define TSASM_ERR_NOMEM (-4)  // the allocator failed; the parser stays usable

// Name of a node's symbol (ids as in the grammar's parser.c after alias resolution, the same as
// ts_node_symbol; names as ts_node_type). "" for an out-of-range id. Thread-safe.
const char *tsasm_language_symbol_name(const TsasmLanguage *lang, uint16_t symbol);
// Number of symbol ids (symbols plus aliases); every node's symbol is below it.
uint32_t tsasm_language_symbol_count(const TsasmLanguage *lang);
// Name of a field id, as ts_language_field_name_for_id; "" for 0 or an out-of-range id. Thread-safe.
const char *tsasm_language_field_name(const TsasmLanguage *lang, uint8_t field);
// Number of fields; field ids run from 1 to it.
uint32_t tsasm_language_field_count(const TsasmLanguage *lang);
#endif
